/**
 * Build `src/data/skyCatalog.json` from published astronomical catalogues.
 *
 * Why this exists as a script rather than a hand-written file: the sky view
 * draws real stars in their real places, and a figure nobody can trace back to
 * a catalogue is a figure somebody made up. Every number in the generated file
 * comes from one of the four sources below and can be regenerated by anyone:
 *
 *   npm run sky:build
 *
 * It is **not** wired into CI. It needs the network, and the sky does not
 * change between releases. Run it by hand when you want to widen the magnitude
 * limit or pick up a new IAU star name, then commit what it writes.
 *
 * Sources, all of them public and all of them cited in the file it writes:
 *
 *   1. Positions, magnitudes, colours, spectral types
 *      Bright Star Catalogue, 5th Revised Ed. (Hoffleit D., Warren Jr W.H.,
 *      1991), VizieR V/50. Equatorial coordinates are J2000, epoch 2000.0.
 *
 *   2. Parallaxes, from which distance in light years is computed
 *      The Hipparcos and Tycho Catalogues (ESA 1997), VizieR I/239/hip_main,
 *      joined to the BSC on Henry Draper number.
 *
 *   3. Proper names ("Sirius", "Vega", ...)
 *      IAU Catalog of Star Names (IAU-CSN), the IAU Division C Working Group
 *      on Star Names. CC-BY: free to use as long as the source is named.
 *
 *   4. Constellation stick figures
 *      d3-celestial `data/constellations.lines.json` (Olaf Frohn, BSD-3-Clause).
 *      Only the *lines* come from here, and lines are a drawing convention
 *      rather than a measurement — see the note in ATTRIBUTION.md. Every vertex
 *      is matched back to a real BSC star by position, and a segment whose
 *      endpoint does not resolve to one is dropped rather than drawn to an
 *      invented point.
 *
 * Two rules the script holds, both of them the reason it is a script:
 *
 *   - A figure is drawn from catalogue stars or it is not drawn. Nothing is
 *     interpolated, nudged or filled in.
 *   - A distance is written only where the Hipparcos parallax is positive and
 *     measured to better than 20%. Below that the number is not a distance, it
 *     is a shrug with a decimal point, and a child reading "550 light years"
 *     deserves better than that.
 */
import { writeFileSync } from 'node:fs';
import { setDefaultAutoSelectFamily } from 'node:net';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

// CDS publishes AAAA records. On a network with no working IPv6 route, Node's
// fetch sits on the v6 address until undici's 10-second connect timeout fires
// and never tries v4, so every request here failed with UND_ERR_CONNECT_TIMEOUT
// while curl to the same URL worked. This makes it try both, as curl does.
setDefaultAutoSelectFamily(true);

const here = dirname(fileURLToPath(import.meta.url));
const OUT = join(here, '..', 'src', 'data', 'skyCatalog.json');

/**
 * 5.3 is roughly what a child sees from a dark site outside a Uzbek city, and
 * it is the point where the stick figures stop losing corners: at 4.6 only 44
 * of the 89 figures have all their stars, at 5.3 it is 84. Going deeper buys
 * three more figures for another 900 stars, which is a worse trade.
 */
const MAG_LIMIT = 5.3;

/** Two vertices are the same star if they agree to this, in degrees. */
const MATCH_TOLERANCE_DEG = 0.05;

/** Hipparcos parallax must be this much better than its own error bar. */
const MIN_PARALLAX_SNR = 5;

const TAP = 'https://tapvizier.cds.unistra.fr/TAPVizieR/tap/sync';
const IAU_CSN = 'https://www.pas.rochester.edu/~emamajek/WGSN/IAU-CSN.txt';
const FIGURES =
  'https://raw.githubusercontent.com/ofrohn/d3-celestial/master/data/constellations.lines.json';

/**
 * Asked for the whole catalogue in one go, the join runs for about four
 * minutes and VizieR answers 503 as often as not. Four narrow magnitude bands
 * each come back in seconds and are easier on a service we do not pay for.
 */
const MAG_BANDS = [-2, 3, 4, 4.7, MAG_LIMIT];

const adqlForBand = (from, to) => `SELECT b.HR AS hr, b.Name AS bayer, b.Vmag AS vmag,
  b.RAJ2000 AS ra, b.DEJ2000 AS de, b.SpType AS sp, b."B-V" AS bv,
  b.HD AS hd, h.HIP AS hip, h.Plx AS plx, h.e_Plx AS eplx
  FROM "V/50/catalog" AS b
  LEFT OUTER JOIN "I/239/hip_main" AS h ON b.HD = h.HD
  WHERE b.Vmag > ${from} AND b.Vmag <= ${to} AND b.RAJ2000 IS NOT NULL`;

/**
 * VizieR answers 503 fairly often under load, and losing a four-minute query to
 * one of those is annoying enough that people stop regenerating the file.
 */
async function text(url, init, attempts = 4) {
  let lastError;
  for (let attempt = 1; attempt <= attempts; attempt += 1) {
    try {
      const res = await fetch(url, init);
      if (res.ok) return res.text();
      lastError = new Error(`${url} answered ${res.status}`);
    } catch (err) {
      lastError = err;
    }
    if (attempt < attempts) {
      process.stdout.write(`(retry ${attempt}) `);
      await new Promise((resolve) => { setTimeout(resolve, attempt * 5000); });
    }
  }
  throw lastError;
}

/** One CSV row; VizieR quotes any field holding a comma or a space. */
function splitCsvLine(line) {
  const out = [];
  let cur = '';
  let quoted = false;
  for (let i = 0; i < line.length; i += 1) {
    const ch = line[i];
    if (quoted) {
      if (ch === '"' && line[i + 1] === '"') { cur += '"'; i += 1; }
      else if (ch === '"') quoted = false;
      else cur += ch;
    } else if (ch === '"') quoted = true;
    else if (ch === ',') { out.push(cur); cur = ''; }
    else cur += ch;
  }
  out.push(cur);
  return out;
}

function parseCsv(body) {
  const lines = body.trim().split('\n');
  const head = splitCsvLine(lines[0]);
  return lines.slice(1).map((line) => {
    const cells = splitCsvLine(line);
    // Deliberately not trimmed: the BSC `Name` field is fixed-width and its
    // leading spaces are what separate the Flamsteed number from the Bayer
    // letter. parseBayer() reads by column.
    return Object.fromEntries(head.map((h, i) => [h, cells[i] ?? '']));
  });
}

const num = (v) => {
  const n = Number.parseFloat(v);
  return Number.isFinite(n) ? n : null;
};

const round = (v, places) =>
  v === null ? null : Number.parseFloat(v.toFixed(places));

/**
 * "  9Alp CMa" — Flamsteed number, then Bayer letter with an optional
 * superscript, then the three-letter constellation. BSC pads all three, and
 * either of the first two can be blank.
 */
function parseBayer(raw) {
  const con = raw.slice(7, 10).trim();
  const greek = raw.slice(3, 7).trim();
  const flamsteed = raw.slice(0, 3).trim();
  return { con, greek, flamsteed };
}

/** Parsecs from milliarcseconds, then light years. 1 pc = 3.2615638 ly. */
function lightYears(parallaxMas) {
  return (1000 / parallaxMas) * 3.2615638;
}

function angularDistance(raA, decA, raB, decB) {
  let dRa = raA - raB;
  if (dRa > 180) dRa -= 360;
  if (dRa < -180) dRa += 360;
  return Math.hypot(dRa * Math.cos((decB * Math.PI) / 180), decA - decB);
}

async function main() {
  const rows = [];
  for (let i = 0; i < MAG_BANDS.length - 1; i += 1) {
    const from = MAG_BANDS[i];
    const to = MAG_BANDS[i + 1];
    process.stdout.write(`Bright Star Catalogue + Hipparcos, V ${from}..${to}... `);
    const csv = await text(TAP, {
      method: 'POST',
      headers: { 'content-type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams({
        REQUEST: 'doQuery', LANG: 'ADQL', FORMAT: 'csv', QUERY: adqlForBand(from, to),
      }),
    });
    const band = parseCsv(csv);
    rows.push(...band);
    console.log(`${band.length} rows`);
  }

  process.stdout.write('IAU Catalog of Star Names... ');
  const csnBody = await text(IAU_CSN);
  console.log('ok');

  process.stdout.write('Constellation figures... ');
  const figuresBody = await text(FIGURES);
  console.log('ok');

  // --- stars -------------------------------------------------------------
  const byHr = new Map();
  const byHip = new Map();
  for (const r of rows) {
    const hr = num(r.hr);
    const ra = num(r.ra);
    const dec = num(r.de);
    const vmag = num(r.vmag);
    if (hr === null || ra === null || dec === null || vmag === null) continue;

    const { con, greek, flamsteed } = parseBayer(r.bayer ?? '');
    const plx = num(r.plx);
    const ePlx = num(r.eplx);
    const trustworthy =
      plx !== null && plx > 0 && ePlx !== null && ePlx > 0 && plx / ePlx >= MIN_PARALLAX_SNR;

    const star = {
      hr,
      hip: num(r.hip),
      ra: round(ra, 4),
      dec: round(dec, 4),
      vmag: round(vmag, 2),
      bv: round(num(r.bv), 2),
      con,
      greek,
      flamsteed,
      spectralType: (r.sp ?? '').trim(),
      // A tenth of a light year is meaningful for Sirius at 8.6 and absurd for
      // Deneb, so the precision follows the number rather than the other way
      // round. Rounding everything to whole light years turned Sirius into 9.
      distanceLy: trustworthy
        ? round(lightYears(plx), lightYears(plx) < 100 ? 1 : 0)
        : null,
    };
    byHr.set(hr, star);
    if (star.hip !== null && !byHip.has(star.hip)) byHip.set(star.hip, star);
  }
  console.log(`  ${byHr.size} stars to magnitude ${MAG_LIMIT}`);
  const withDistance = [...byHr.values()].filter((s) => s.distanceLy !== null).length;
  console.log(`  ${withDistance} have a parallax good enough to quote a distance`);

  // --- IAU proper names ---------------------------------------------------
  // Columns are fixed-width; HIP is the one identifier both catalogues share
  // for every entry, so the join is on that and nothing else.
  let named = 0;
  for (const line of csnBody.split('\n')) {
    if (!line || line.startsWith('#') || line.startsWith('$')) continue;
    const name = line.slice(0, 18).trim();
    const hip = num(line.slice(89, 96));
    if (!name || hip === null) continue;
    const star = byHip.get(hip);
    if (!star || star.properName) continue;
    star.properName = name;
    named += 1;
  }
  console.log(`  ${named} carry an IAU proper name`);

  // --- constellation figures ----------------------------------------------
  const figures = JSON.parse(figuresBody);
  const stars = [...byHr.values()];
  const resolve = (ra, dec) => {
    let best = null;
    let bestDist = Infinity;
    for (const s of stars) {
      const d = angularDistance(s.ra, s.dec, ra, dec);
      if (d < bestDist) { bestDist = d; best = s; }
    }
    return bestDist <= MATCH_TOLERANCE_DEG ? best : null;
  };

  const lines = {};
  let kept = 0;
  let dropped = 0;
  for (const feature of figures.features) {
    const segments = [];
    for (const polyline of feature.geometry.coordinates) {
      const resolved = polyline.map(([lon, lat]) => resolve(((lon % 360) + 360) % 360, lat));
      // A polyline is a chain; keep each link whose two ends are both real
      // stars, and let an unresolvable vertex break the chain rather than
      // take the whole figure down with it.
      for (let i = 0; i < resolved.length - 1; i += 1) {
        const a = resolved[i];
        const b = resolved[i + 1];
        if (a && b) { segments.push([a.hr, b.hr]); kept += 1; }
        else dropped += 1;
      }
    }
    if (segments.length) lines[feature.id] = segments;
  }
  console.log(`  ${Object.keys(lines).length} figures, ${kept} links, ${dropped} dropped`);

  // --- write --------------------------------------------------------------
  // Tuples rather than objects: the same data as named fields is three times
  // the bytes, and this file is shipped to a phone on a school connection.
  // `starFields` is the contract; readCatalog() in src/data/skyCatalog.js is
  // the only thing allowed to know the order.
  const STAR_FIELDS = [
    'hr', 'ra', 'dec', 'vmag', 'bv', 'con', 'greek', 'name', 'distanceLy', 'spectralType',
  ];
  const ordered = stars.sort((a, b) => a.vmag - b.vmag);
  const payload = {
    _comment:
      'Generated by frontend/scripts/build-sky-catalog.mjs. Do not edit by hand — ' +
      'run `npm run sky:build` and commit what it writes. Sources are named in ' +
      'src/data/ATTRIBUTION.md and in the script header.',
    generatedAt: new Date().toISOString().slice(0, 10),
    magnitudeLimit: MAG_LIMIT,
    equinox: 'J2000.0',
    sources: {
      positions: 'Bright Star Catalogue, 5th Revised Ed. (Hoffleit+ 1991), VizieR V/50',
      parallaxes: 'The Hipparcos and Tycho Catalogues (ESA 1997), VizieR I/239/hip_main',
      names: 'IAU Catalog of Star Names, IAU WGSN',
      figures: 'd3-celestial constellations.lines.json (Olaf Frohn, BSD-3-Clause)',
    },
    starFields: STAR_FIELDS,
    stars: ordered.map((s) => [
      s.hr, s.ra, s.dec, s.vmag, s.bv, s.con, s.greek,
      s.properName ?? '', s.distanceLy, s.spectralType || '',
    ]),
    figures: lines,
  };

  writeFileSync(OUT, `${JSON.stringify(payload)}\n`, 'utf8');
  const kb = Math.round(JSON.stringify(payload).length / 1024);
  console.log(`\nWrote ${OUT} (${kb} KB)`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
